UPDATE PRATICAS P JOIN VW_LOTE_ETIQUETAS L ON L.ID = P.ID AND L.CHAVE = '{{chave}}' SET P.JEITO = NULLIF(L.JEITO, ''), P.SERVE = NULLIF(L.SERVE, ''), P.QUANDO = NULLIF(L.QUANDO, ''), P.CONSELHO = IFNULL(L.CONSELHO, 0), P.REVISADA_EM = DATE_FORMAT(NOW() - INTERVAL 3 HOUR, '%Y-%m-%dT%H:%i:%s'), P.FINALIDADE_EM = DATE_FORMAT(NOW() - INTERVAL 3 HOUR, '%Y-%m-%dT%H:%i:%s')